#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998;
    long long inv_n_plus_m;
    std::vector<long long> fact, inv_fact;

    long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long pow_mod(long long base, long long exp) {
        long long result = 1;
        long long cur = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = mult(result, cur);
            cur = mult(cur, cur);
            exp >>= 1;
        }
        return result;
    }

    long long inv(long long a) {
        // Fermat's little theorem since MOD is prime
        return pow_mod(a, MOD - 2);
    }

    void fInv(long long n) {
        inv_n_plus_m = inv(n);
        fact.resize(n + 1);
        inv_fact.resize(n + 1);
        fact[0] = 1;
        for (long long i = 1; i <= n; i++) {
            fact[i] = mult(fact[i - 1], i);
        }
        inv_fact[n] = inv(fact[n]);
        for (long long i = n - 1; i >= 0; i--) {
            inv_fact[i] = mult(inv_fact[i + 1], i + 1);
        }
    }

    long long ncr(long long n, long long r) {
        if (r < 0 || r > n) return 0;
        return mult(fact[n], mult(inv_fact[r], inv_fact[n - r]));
    }

    long long paritySign(long long k) {
        // sign alternates: +, -, +, ...
        return (k % 2 == 0) ? MOD - 1 : 1;
    }

    long long div(long long a, long long b) {
        return mult(a, inv(b));
    }

    long long smallInv(long long a) {
        return inv(a);
    }

    long long mult(long long a, long long b, long long c = 1, long long d = 1) {
        long long res = mult(a, b);
        res = mult(res, c);
        res = mult(res, d);
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    Mod998 mod;
    mod.fInv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, n - i, mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = mod.div(m + k, k);
        long long term = mod.mult(sign, mod.ncr(n, k), numPhases, phaseSize);
        answer = mod.add(answer, term);
    }

    cout << answer << "\n";

    return 0;
}
